function localMatchScore(source,track){const words=value=>String(value||'').toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/).filter(Boolean);const overlap=(left,right)=>{const a=words(left),b=new Set(words(right));return a.length?a.filter(word=>b.has(word)).length/a.length:0};return .68*overlap(source.title,track.title)+.32*overlap(source.artist,track.artist)}
function splitFilenameParts(path,separator){const filename=String(path||'').split(/[\\/]/).pop()||'';const base=filename.replace(/\.[^.]+$/,'');const chunks=separator?base.split(separator).map(value=>value.trim()):[base];const first=(chunks[0]||'').match(/^(?:\[?\s*)(\d{1,3})(?:\s*\]?[.)])?\s*(.*)$/);const prefixTrack=!!first&&!first[2].trim();return chunks.map((value,index)=>{let field='',clean=value;if(index===0&&first){clean=first[2].trim();if(clean){field='artist'}else{field='track';clean=String(Number(first[1]))}}else if(chunks.length===2)field=index===0?'artist':'title';else if(chunks.length>=3){const artistIndex=prefixTrack?1:0;field=index===artistIndex?'artist':index===chunks.length-1?'title':index===artistIndex+1&&chunks.length>3?'album':''}return{value:clean||value,field,enabled:!!field}})}
function formatDuration(seconds){const total=Math.max(0,Math.floor(Number(seconds)||0));const hours=Math.floor(total/3600);const minutes=Math.floor((total%3600)/60);const secs=total%60;return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(secs).padStart(2,'0')}`}
function formatLibraryDuration(seconds){let remaining=Math.max(0,Math.floor(Number(seconds)||0));const units=[['J',365*86400],['M',30*86400],['T',86400],['h',3600],['m',60],['s',1]];return units.map(([label,size])=>{const value=Math.floor(remaining/size);remaining%=size;return `${value}${label}`}).join(' ')}
function parseLrcLyrics(lyrics){return String(lyrics||'').split(/\r?\n/).flatMap(line=>{const stamps=[...line.matchAll(/\[(\d{2,}):(\d{2})(?:[.:](\d{1,3}))?\]/g)];const text=line.replace(/\[\d{2,}:\d{2}(?:[.:]\d{1,3})?\]/g,'').trim();return stamps.map(match=>({seconds:Number(match[1])*60+Number(match[2])+Number((match[3]||'0').padEnd(3,'0'))/1000,text}))}).sort((a,b)=>a.seconds-b.seconds)}
function pathWithin(path,root){const normalized=value=>String(value||'').replaceAll('\\','/').replace(/\/+$/,'').toLocaleLowerCase();const file=normalized(path),folder=normalized(root);return file===folder||file.startsWith(folder+'/')}
