 const [pictures,setPictures]=useState([]),[index,setIndex]=useState(0),[newType,setNewType]=useState('CoverFront'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[imageFailed,setImageFailed]=useState(false),[removePrompt,setRemovePrompt]=useState(false);
 const refresh=async()=>{if(!path){setPictures([]);return}try{const next=await invoke('get_track_pictures',{path});setPictures(next);setIndex(i=>Math.min(i,Math.max(0,next.length-1)));setImageFailed(false);setError('')}catch(e){setError(`Cover konnte nicht aus der Datei gelesen werden: ${String(e)}`)}};
