function manipulateText(value,action,options){const text=String(value??'');const chars=Array.from(text);const count=Math.max(0,Math.floor(Number(options.count)||0));const position=Math.max(1,Math.floor(Number(options.position)||1))-1;switch(action){case'insertBeginning':return options.text+text;case'insertEnd':return text+options.text;case'insertAtPosition':return [...chars.slice(0,position),...Array.from(options.text),...chars.slice(position)].join('');case'removeBeginning':return options.text&&text.startsWith(options.text)?text.slice(options.text.length):text;case'removeEnd':return options.text&&text.endsWith(options.text)?text.slice(0,-options.text.length):text;case'removeText':return options.text?text.split(options.text).join(''):text;case'removeNBeginning':return chars.slice(count).join('');case'removeNEnd':return count?chars.slice(0,Math.max(0,chars.length-count)).join(''):text;case'removeRange':{const start=Math.max(1,Math.floor(Number(options.start)||1))-1;const end=Math.max(start,Math.floor(Number(options.end)||start+1));return [...chars.slice(0,start),...chars.slice(end)].join('')}case'uppercase':return text.toLocaleUpperCase();case'lowercase':return text.toLocaleLowerCase();case'titleCase':return text.toLocaleLowerCase().replace(/(^|[\s\-_'’])([\p{L}\p{N}])/gu,(_,space,letter)=>space+letter.toLocaleUpperCase());case'sentenceCase':return text.toLocaleLowerCase().replace(/(^\s*|[.!?]\s+)([\p{L}])/gu,(_,space,letter)=>space+letter.toLocaleUpperCase());case'capitalizeWords':return text.replace(/(^|[\s\-_'’])([\p{L}\p{N}])/gu,(_,space,letter)=>space+letter.toLocaleUpperCase());case'replaceText':return options.find?text.split(options.find).join(options.replacement):text;default:return text}}
