function tagCompleteness(track,artwork){const missing=COMPLETENESS_FIELDS.filter(([key])=>{if(key==='artwork')return !artwork;const value=String(track?.[key]??'').trim();if(!value)return true;if(key==='artist'&&value==='Unbekannter Interpret')return true;if(key==='album'&&value==='Unbekanntes Album')return true;if(key==='title'&&track?.path){const filename=track.path.split(/[\\/]/).pop()?.replace(/\.[^.]+$/,'');if(filename&&filename.toLowerCase()===value.toLowerCase())return true}return false}).map(([,label])=>label);return{missing,percent:Math.round((COMPLETENESS_FIELDS.length-missing.length)/COMPLETENESS_FIELDS.length*100)}}
