 async function fetchLyricsFor(track){if(!track?.path){setLyricsError('Wähle zuerst einen importierten Titel aus.');return}const request=++lyricsRequestRef.current;setLyricsPath(track.path);setLyricsBusy(true);setLyricsError('');setLyricsResults([]);setLyricsSelected(null);const seconds=String(track.duration||'').split(':').reduce((total,part)=>total*60+(Number(part)||0),0);try{const results=await invoke('search_lyrics',{title:track.title,artist:track.artist==='Unbekannter Interpret'?'':track.artist,album:track.album==='Unbekanntes Album'?'':track.album,duration:seconds});if(request!==lyricsRequestRef.current)return;setLyricsResults(results);setLyricsSelected(results[0]?.id??null);if(!results.length)setLyricsError('Keine Lyrics gefunden. Du kannst den Titel später erneut suchen.')}catch(error){if(request===lyricsRequestRef.current)setLyricsError(String(error))}finally{if(request===lyricsRequestRef.current)setLyricsBusy(false)}}
