 async function saveLyricsSidecar(overwrite=false){const candidate=lyricsResults.find(item=>item.id===lyricsSelected);if(!candidate||!lyricsPath)return;const synced=lyricsSynced&&!!candidate.syncedLyrics;const lyrics=synced?candidate.syncedLyrics:candidate.plainLyrics||candidate.syncedLyrics;if(!lyrics){setLyricsError('Für diesen Treffer ist kein Liedtext verfügbar.');return}setLyricsSaving(true);setLyricsError('');try{const saved=await invoke('save_lyrics_sidecar',{path:lyricsPath,lyrics,synced,overwrite});setLyricsError(`Gespeichert: ${saved.split(/[\\/]/).pop()}`)}catch(error){const message=String(error);if(message.startsWith('EXISTS:')&&!overwrite){const target=message.slice(7);if(window.confirm(`„${target.split(/[\\/]/).pop()}“ existiert bereits. Soll die Lyrics-Datei ersetzt werden?`)){await saveLyricsSidecar(true);return}}else setLyricsError(`Lyrics konnten nicht gespeichert werden: ${message}`)}finally{setLyricsSaving(false)}}
 async function scanDuplicates(){const paths=tracks.map(t=>t.path).filter(Boolean);if(!paths.length){setDuplicateGroups([]);return}setDuplicateScanning(true);setDuplicateError('');try{setDuplicateGroups(await invoke('find_duplicates',{paths}))}catch(error){setDuplicateError(String(error));setDuplicateGroups([])}finally{setDuplicateScanning(false)}}
 async function trashDuplicateGroup(group){const keepPath=duplicateKeepByGroup[group.paths[0]]||group.paths[0];const duplicatePaths=group.paths.filter(path=>path!==keepPath);if(!duplicatePaths.length)return;const names=duplicatePaths.map(path=>path.split(/[\\/]/).pop()).join('\n');if(!window.confirm(`Diese ${duplicatePaths.length} identische(n) Kopie(n) in den System-Papierkorb verschieben?\n\nBehalten: ${keepPath.split(/[\\/]/).pop()}\n\n${names}`))return;try{const outcomes=await invoke('trash_duplicate_copies',{keepPath,duplicatePaths});const succeeded=outcomes.filter(([,result])=>result?.Ok===null).length;const failures=outcomes.filter(([,result])=>result?.Err);const fresh=(await invoke('list_tracks')).map(fromNative);setTracks(fresh);await refreshAnalyses();await refreshFavorites();setSelected(index=>Math.min(index,Math.max(0,fresh.length-1)));setPlaylists(await invoke('list_playlists'));if(activePlaylist)setPlaylistTracks((await invoke('get_playlist_tracks',{playlistId:activePlaylist})).map(fromNative));setDuplicateGroups(await invoke('find_duplicates',{paths:fresh.map(track=>track.path)}));note(`${succeeded} Datei(en) in den Papierkorb verschoben${failures.length?` · ${failures.length} Fehler`:''}`)}catch(error){note(`Duplikate konnten nicht verschoben werden: ${error}`)}}
 function setField(field,value){setTracks(ts=>{if(!ts[selected])return ts;const next=ts.slice();next[selected]={...next[selected],[field]:value};return next})}
 async function saveTags(){const t=tracks[selected];if(!t?.path){note('Diese Beispieldatei hat keinen lokalen Dateipfad');return}try{const result=await invoke('write_tags',{changes:[{path:t.path,title:t.title,artist:t.artist,album:t.album,albumArtist:t.albumArtist,year:t.year??'',genre:t.genre,track:t.track??'',disc:t.disc??'',trackTotal:t.trackTotal??'',discTotal:t.discTotal??'',compilation:!!t.compilation,extraTags:Object.fromEntries(EXTRA_TAG_FIELDS.map(key=>[key,t[key]||'']))}]});const row=result[0];if(row?.[1]?.Ok===null){const fresh=fromNative(await invoke('inspect_file',{path:t.path}));setTracks(list=>list.map(item=>item.path===t.path?fresh:item));setPlaylistTracks(list=>list.map(item=>item.path===t.path?fresh:item));setEdit(false);await refreshHistory();await refreshAnalyses();note('Tags gespeichert · Datei neu eingelesen · Änderung ist im Verlauf')}else note(`Schreiben fehlgeschlagen: ${row?.[1]?.Err||'Unbekannter Fehler'}`)}catch(e){note(`Tag-Schreiben nicht verfügbar: ${e}`)}}
 async function analyzePaths(paths){const unique=[...new Set(paths.filter(Boolean))];if(!unique.length){note('Wähle zuerst importierte Titel aus');return}setAnalysing(true);setAnalysisResults([]);setAnalysisProgress({done:0,total:unique.length,title:''});const analyzed=[];const results=[];for(let i=0;i<unique.length;i++){const path=unique[i];const track=tracks.find(item=>item.path===path);setAnalysisProgress({done:i+1,total:unique.length,title:track?.title||path.split(/[\\/]/).pop()});try{const result=await invoke('analyze_bpm',{path});analyzed.push({path,extraTags:{bpm:String(Math.round(result.bpm)),key:result.key}});results.push({path,title:track?.title||path.split(/[\\/]/).pop(),bpm:Math.round(result.bpm),confidence:Math.round(result.confidence*100),key:result.keyName,tagKey:result.key,camelot:result.camelot,keyConfidence:Math.round(result.keyConfidence*100),beatOffset:result.beatOffsetSeconds,ok:false})}catch(error){results.push({path,title:track?.title||path.split(/[\\/]/).pop(),ok:false,error:String(error)})}setAnalysisResults([...results])}if(analyzed.length){try{const writes=await invoke('write_tags',{changes:analyzed});for(const [path,out] of writes){const row=results.find(item=>item.path===path);if(row){row.ok=out?.Ok===null;if(!row.ok)row.error=out?.Err||'Analyse-Tags konnten nicht geschrieben werden'}}const persisted=results.filter(item=>item.ok);if(persisted.length){const savedAnalyses=persisted.map(item=>({path:item.path,bpm:item.bpm,confidence:item.confidence/100,key:item.tagKey,keyName:item.key,camelot:item.camelot,keyConfidence:item.keyConfidence/100,beatOffsetSeconds:item.beatOffset}));try{await invoke('save_track_analyses',{analyses:savedAnalyses});setAnalysisByPath(state=>({...state,...Object.fromEntries(savedAnalyses.map(item=>[item.path,item]))}))}catch(error){note(`Analyse wurde berechnet, Beatstart konnte nicht gespeichert werden: ${error}`)}}const fresh=(await invoke('list_tracks')).map(fromNative);setTracks(fresh);if(activePlaylist)setPlaylistTracks((await invoke('get_playlist_tracks',{playlistId:activePlaylist})).map(fromNative));await refreshHistory()}catch(error){for(const row of results.filter(item=>analyzed.some(item2=>item2.path===item.path)))row.error=String(error)}}setAnalysisResults([...results]);setAnalysisProgress({done:unique.length,total:unique.length,title:''});setAnalysing(false);const success=results.filter(item=>item.ok).length;note(`Audioanalyse abgeschlossen · ${success} von ${unique.length} gespeichert${unique.length>success?` · ${unique.length-success} ohne Ergebnis`:''}`)}
