 function beginTextEditor(){setTextTargetMode(checkedPaths.some(Boolean)?'selected':'all');setTextOperationResult('');setTextPreview(false);setTextEditorOpen(true)}
 async function applyTextManipulation(){const targets=textTargetMode==='selected'?tracks.filter(track=>track.path&&checkedPathSet.has(track.path)):tracks.filter(track=>track.path);if(!targets.length){note(textTargetMode==='selected'?'Markiere zuerst mindestens eine Datei':'Die Bibliothek enthält keine importierten Dateien');return}if(['removeBeginning','removeEnd','removeText','replaceText'].includes(textAction)&&!textFind.trim()){note('Gib den zu suchenden Text ein');return}if(['insertBeginning','insertEnd','insertAtPosition'].includes(textAction)&&!textInput){note('Gib den einzufügenden Text ein');return}if(['removeNBeginning','removeNEnd'].includes(textAction)&&Number(textCount)<1){note('Die Zeichenanzahl muss mindestens 1 sein');return}if(textAction==='removeRange'&&Number(textRangeEnd)<Number(textRangeStart)){note('Das Bereichsende muss hinter dem Anfang liegen');return}const options={text:['removeBeginning','removeEnd','removeText','replaceText'].includes(textAction)?textFind:textInput,find:textFind,replacement:textReplacement,position:textPosition,count:textCount,start:textRangeStart,end:textRangeEnd};const directFields=new Set(['title','artist','album','albumArtist','genre']);const changes=targets.flatMap(track=>{const before=String(track[textField]??'');const after=manipulateText(before,textAction,options);if(after===before)return[];const change={path:track.path};if(directFields.has(textField))change[textField]=after;else change.extraTags={[textField]:after};return[change]});if(!changes.length){setTextOperationResult('Keine Änderungen erforderlich.');return}setTextOperationBusy(true);setTextOperationResult('');try{const results=await invoke('write_tags',{changes});const successful=results.filter(([,out])=>out?.Ok===null).length;const fresh=(await invoke('list_tracks')).map(fromNative);setTracks(fresh);if(activePlaylist)setPlaylistTracks((await invoke('get_playlist_tracks',{playlistId:activePlaylist})).map(fromNative));await refreshHistory();await refreshAnalyses();const summary=`${successful} von ${changes.length} Datei(en) aktualisiert`;setTextOperationResult(summary);note(`${summary} · Sicherung und Verlauf gespeichert`);if(closeTextEditorWhenDone)setTextEditorOpen(false)}catch(error){const message=`Textbearbeitung fehlgeschlagen: ${error}`;setTextOperationResult(message);note(message)}finally{setTextOperationBusy(false)}}
 async function applyBatch(){const targets=batchTargets;if(!targets.length){note('Die Auswahl enthält keine importierten Dateien');return}const numeric=new Set(['year','track','disc','trackTotal','discTotal']);const changes=targets.map(t=>{const c={path:t.path};for(const [field,value] of Object.entries(batchDraft)){if(value===''||value==null)continue;c[field]=field==='year'||field==='track'||field==='disc'?String(value):field==='compilation'?value==='true':value}return c});if(changes.some(c=>Object.entries(c).some(([k,v])=>numeric.has(k)&&k!=='path'&&(!Number.isInteger(Number(v))||Number(v)<0)))){note('Jahr, Track- und Discnummer müssen ganze Zahlen ab 0 sein');return}try{const result=await invoke('write_tags',{changes});const normalized=result.map(([path,out])=>({path,ok:out?.Ok===null,error:out?.Err||''}));setBatchResults(normalized);const refreshed=await invoke('list_tracks');setTracks(refreshed.map(fromNative));await refreshHistory();await refreshAnalyses();note(`${normalized.filter(x=>x.ok).length} von ${normalized.length} Dateien aktualisiert`)}catch(e){note(`Batch konnte nicht geschrieben werden: ${e}`)}}
