 function toggleColumn(key){if(key==='title')return;setVisibleColumns(columns=>columns.includes(key)?columns.filter(item=>item!==key):[...columns,key])}
 function reorderColumn(source,target){if(!source||source===target)return;setVisibleColumns(columns=>{const next=[...columns],from=next.indexOf(source),to=next.indexOf(target);if(from<0||to<0)return columns;next.splice(from,1);next.splice(to,0,source);return next});columnDragRef.current=null}
 function startColumnDrag(event,key){event.preventDefault();event.stopPropagation();const th=event.currentTarget.closest('th');columnPointerRef.current={source:key,target:key,pointerId:event.pointerId,moved:false,startX:event.clientX,startY:event.clientY,startWidth:th?.getBoundingClientRect().width};event.currentTarget.setPointerCapture(event.pointerId);suppressHeaderSortUntilRef.current=Date.now()+600}
 function moveColumnDrag(event){const drag=columnPointerRef.current;if(!drag||drag.pointerId!==event.pointerId)return;const element=document.elementFromPoint(event.clientX,event.clientY)?.closest('th[data-column-key]');if(!element)return;const target=element.dataset.columnKey;if(target&&target!==drag.target){drag.target=target;drag.moved=true;document.querySelectorAll('.track-table th[data-column-key]').forEach(th=>th.classList.toggle('column-drop-target',th.dataset.columnKey===target))}}
