 function resizeColumn(event,key){event.preventDefault();event.stopPropagation();const startX=event.clientX,startWidth=columnWidths[key]||TABLE_COLUMN_WIDTHS[key]||120;const move=e=>setColumnWidths(widths=>({...widths,[key]:Math.max(60,Math.min(700,startWidth+e.clientX-startX))}));const up=()=>{window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up)};window.addEventListener('mousemove',move);window.addEventListener('mouseup',up)}
 function renderTrackCell(key,track){switch(key){case'cover':return <td className="cover-cell" style={{width:columnWidths.cover||TABLE_COLUMN_WIDTHS.cover}}><span className="table-cover">{artworkByPath[track.path]?<img src={artworkByPath[track.path]} alt={`Cover: ${track.album||track.title}`}/>:<Disc3 size={15}/>}</span></td>;case'title':return <td style={{width:columnWidths.title||TABLE_COLUMN_WIDTHS.title}}><div className="track-name"><b title={track.title}>{track.title}</b></div></td>;case'artist':return <td style={{width:columnWidths.artist||TABLE_COLUMN_WIDTHS.artist}} title={track.artist}>{track.artist}</td>;case'album':return <td style={{width:columnWidths.album||TABLE_COLUMN_WIDTHS.album}} title={track.album}>{track.album}</td>;case'genre':return <td style={{width:columnWidths.genre||TABLE_COLUMN_WIDTHS.genre}}><span className="genre-pill">{track.genre||'—'}</span></td>;case'bpm':return <td style={{width:columnWidths.bpm||TABLE_COLUMN_WIDTHS.bpm}}><span className="bpm">{track.bpm}</span></td>;case'key':return <td style={{width:columnWidths.key||TABLE_COLUMN_WIDTHS.key}}><span className="key-pill">{track.key}</span></td>;case'duration':return <td className="duration" style={{width:columnWidths.duration||TABLE_COLUMN_WIDTHS.duration}}>{track.duration}</td>;case'bitrate':return <td className="duration" style={{width:columnWidths.bitrate||TABLE_COLUMN_WIDTHS.bitrate}}>{track.bitrate?`${track.bitrate} kb/s`:'—'}</td>;case'sampleRate':return <td className="duration" style={{width:columnWidths.sampleRate||TABLE_COLUMN_WIDTHS.sampleRate}}>{track.sampleRate?`${(track.sampleRate/1000).toFixed(track.sampleRate%1000?1:0)} kHz`:'—'}</td>;case'channels':return <td className="duration" style={{width:columnWidths.channels||TABLE_COLUMN_WIDTHS.channels}}>{track.channels?`${track.channels} ch`:'—'}</td>;case'bitDepth':return <td className="duration" style={{width:columnWidths.bitDepth||TABLE_COLUMN_WIDTHS.bitDepth}}>{track.bitDepth?`${track.bitDepth} bit`:'—'}</td>;case'format':return <td style={{width:columnWidths.format||TABLE_COLUMN_WIDTHS.format}}><span className={'format '+track.format.toLowerCase()}>{track.format}</span></td>;case'rating':return <td style={{width:columnWidths.rating||TABLE_COLUMN_WIDTHS.rating}}><span className="rating">★★★★<i>★</i></span></td>;default:return null}}
 async function chooseSort(field){setSortBy(field);setSortDirection('asc');setSortMenuOpen(false);if(view==='playlists'&&field!=='library')await sortCurrentPlaylist(field,'asc')}
 function sortFromHeader(field){if(Date.now()<suppressHeaderSortUntilRef.current)return;const direction=sortBy===field?(sortDirection==='asc'?'desc':'asc'):'asc';setSortBy(field);setSortDirection(direction);if(view==='playlists')void sortCurrentPlaylist(field,direction)}
 async function sortCurrentPlaylist(field='title',direction='asc'){if(!activePlaylist||playlistTracks.length<2)return;const factor=direction==='desc'?-1:1;const ordered=[...playlistTracks].sort((a,b)=>factor*(field==='bpm'?(parseFloat(a.bpm)||Infinity)-(parseFloat(b.bpm)||Infinity):field==='duration'?(parseInt(a.duration)*60+parseInt(a.duration.split(':')[1]||'0'))-(parseInt(b.duration)*60+parseInt(b.duration.split(':')[1]||'0')):String(a[field]||'').localeCompare(String(b[field]||''),'de',{numeric:true,sensitivity:'base'}))).map(item=>item.path);try{await invoke('reorder_playlist_tracks',{playlistId:activePlaylist,paths:ordered});setPlaylistTracks((await invoke('get_playlist_tracks',{playlistId:activePlaylist})).map(fromNative));note(`Playlist nach ${field==='title'?'Titel':field==='artist'?'Interpret':field==='album'?'Album':field==='bpm'?'BPM':'Dauer'} sortiert`)}catch(error){note(`Playlist konnte nicht sortiert werden: ${error}`)}}
